    [InlineData("Martínez, Andrés", "martinez andres")]
    [InlineData("Andres    Martinez", "andres martinez")]
    [InlineData("  hola  ", "hola")]
    [InlineData("¿Cuál es mi promedio?", "cual es mi promedio")]
