        "¿Dónde queda Bienestar?"
    };

    public static TheoryData<string> PreguntasDeCoordinadorConMarcador => new()
    {
        "¿Cuál es mi promedio?",
        "¿Cuántas faltas tengo?",
        "Quiero ver mis notas"
    };

